"""
EPUB Builder for The Cindy Lou Legal Capers
Generates KDP-compliant EPUB 3 files for all three books.
"""
import os
import re
from datetime import datetime

# Check for required packages
try:
    from ebooklib import epub
    HAS_EBOOKLIB = True
except ImportError:
    HAS_EBOOKLIB = False
    print("ebooklib not available, will use manual EPUB generation")

def slugify(text):
    """Create a URL-safe slug from text."""
    return re.sub(r'[^a-z0-9]+', '-', text.lower()).strip('-')

def build_epub_manual(book_dir, book_title, book_subtitle, series_name, book_num, author="Bob J Mills"):
    """Build EPUB using manual ZIP-based approach (no external dependencies beyond standard library)."""
    import zipfile
    from io import BytesIO

    chapters_dir = os.path.join(book_dir, "chapters")
    output_dir = os.path.join(book_dir, "output")
    os.makedirs(output_dir, exist_ok=True)

    # Collect chapters
    chapters = []
    for i in range(1, 31):
        ch_path = os.path.join(chapters_dir, f"ch{i:02d}.md")
        if os.path.exists(ch_path):
            with open(ch_path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                chapters.append((i, content))

    if not chapters:
        print(f"No chapters found for {book_title}")
        return None

    slug = slugify(book_title)
    epub_path = os.path.join(output_dir, f"{slug}.epub")

    # Build EPUB (ZIP with specific structure)
    with zipfile.ZipFile(epub_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        # mimetype must be first and uncompressed
        mimetype = b'application/epub+zip'
        zf.writestr('mimetype', mimetype, compress_type=zipfile.ZIP_STORED)

        # META-INF/container.xml
        container_xml = '''<?xml version="1.0" encoding="UTF-8"?>
<container version="1.0" xmlns="urn:oasis:names:tc:opendocument:xmlns:container">
  <rootfiles>
    <rootfile full-path="OEBPS/content.opf" media-type="application/oebps-package+xml"/>
  </rootfiles>
</container>'''
        zf.writestr('META-INF/container.xml', container_xml)

        # CSS
        css = '''@namespace epub "http://www.idpf.org/2007/ops";

body {
    font-family: Georgia, "Times New Roman", serif;
    font-size: 1em;
    line-height: 1.6;
    margin: 0;
    padding: 0;
    color: #000;
}

h1 {
    font-size: 1.8em;
    font-weight: bold;
    text-align: center;
    margin-top: 2em;
    margin-bottom: 1em;
    page-break-before: always;
}

h2 {
    font-size: 1.4em;
    font-weight: bold;
    text-align: center;
    margin-top: 1.5em;
    margin-bottom: 0.8em;
    page-break-before: always;
}

h3 {
    font-size: 1.2em;
    font-weight: bold;
    margin-top: 1.2em;
    margin-bottom: 0.6em;
}

p {
    text-indent: 1.5em;
    margin: 0;
    padding: 0;
}

p.no-indent {
    text-indent: 0;
}

.scene-break {
    text-align: center;
    margin: 1.5em 0;
    text-indent: 0;
}

.title-page {
    text-align: center;
    padding-top: 30%;
}

.title-page h1 {
    font-size: 2.5em;
    page-break-before: auto;
}

.title-page h2 {
    font-size: 1.3em;
    font-style: italic;
    page-break-before: auto;
}

.title-page .author {
    font-size: 1.1em;
    margin-top: 2em;
}

.toc-entry {
    margin: 0.5em 0;
}

.copyright {
    font-size: 0.85em;
    text-align: center;
    margin: 2em 1em;
}

img {
    max-width: 100%;
    height: auto;
    display: block;
    margin: 1em auto;
}

.chapter-image {
    text-align: center;
    margin: 1em 0;
    page-break-after: avoid;
}
'''
        zf.writestr('OEBPS/styles.css', css)

        # Cover image
        cover_path = f"/home/bob/cindy-lou-series/covers/{slug}_cover.png"
        if os.path.exists(cover_path):
            with open(cover_path, 'rb') as f:
                cover_data = f.read()
            zf.writestr('OEBPS/images/cover.png', cover_data)

        # Build content.opf manifest and spine
        manifest_items = []
        spine_items = []
        item_id = 0

        # CSS
        manifest_items.append(f'<item id="css" href="styles.css" media-type="text/css"/>')

        # Cover image
        if os.path.exists(cover_path):
            manifest_items.append(f'<item id="cover-img" href="images/cover.png" media-type="image/png" properties="cover-image"/>')

        # Cover page
        cover_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>Cover</title><link rel="stylesheet" href="styles.css"/></head>
<body>
<div class="title-page">
<img src="images/cover.png" alt="{book_title}" style="max-width:100%;height:auto;"/>
</div>
</body>
</html>'''
        zf.writestr('OEBPS/cover.xhtml', cover_xhtml)
        manifest_items.append(f'<item id="cover" href="cover.xhtml" media-type="application/xhtml+xml"/>')
        spine_items.append('<itemref idref="cover"/>')

        # Title page
        title_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>Title Page</title><link rel="stylesheet" href="styles.css"/></head>
<body>
<div class="title-page">
<h1>{book_title}</h1>
<h2>{book_subtitle}</h2>
<p class="author">{author}</p>
</div>
</body>
</html>'''
        zf.writestr('OEBPS/titlepage.xhtml', title_xhtml)
        manifest_items.append(f'<item id="titlepage" href="titlepage.xhtml" media-type="application/xhtml+xml"/>')
        spine_items.append('<itemref idref="titlepage"/>')

        # Copyright page
        year = datetime.now().year
        copyright_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>Copyright</title><link rel="stylesheet" href="styles.css"/></head>
<body class="copyright">
<p><strong>{book_title}</strong></p>
<p><em>{book_subtitle}</em></p>
<p>&copy; {year} {author}</p>
<p>All rights reserved.</p>
<p>This is a work of fiction. Names, characters, places, and incidents are either the product of the author's imagination or are used fictitiously.</p>
<p><br/>{series_name} — Book {book_num}</p>
<p><br/><em>AI Disclosure: This book was written with AI assistance. The story, characters, and voice are original works by {author}.</em></p>
</body>
</html>'''
        zf.writestr('OEBPS/copyright.xhtml', copyright_xhtml)
        manifest_items.append(f'<item id="copyright" href="copyright.xhtml" media-type="application/xhtml+xml"/>')
        spine_items.append('<itemref idref="copyright"/>')

        # TOC page
        toc_entries = ''
        for ch_num, _ in chapters:
            toc_entries += f'<p class="toc-entry"><a href="ch{ch_num:02d}.xhtml">Chapter {ch_num}</a></p>\n'

        toc_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>Table of Contents</title><link rel="stylesheet" href="styles.css"/></head>
<body>
<h2>Table of Contents</h2>
{toc_entries}
</body>
</html>'''
        zf.writestr('OEBPS/toc.xhtml', toc_xhtml)
        manifest_items.append(f'<item id="toc" href="toc.xhtml" media-type="application/xhtml+xml"/>')
        spine_items.append('<itemref idref="toc"/>')

        # nav.xhtml (EPUB3 navigation)
        nav_entries = '<li><a href="cover.xhtml">Cover</a></li>\n'
        nav_entries += '<li><a href="titlepage.xhtml">Title Page</a></li>\n'
        nav_entries += '<li><a href="copyright.xhtml">Copyright</a></li>\n'
        nav_entries += '<li><a href="toc.xhtml">Table of Contents</a></li>\n'
        for ch_num, _ in chapters:
            nav_entries += f'<li><a href="ch{ch_num:02d}.xhtml">Chapter {ch_num}</a></li>\n'

        nav_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml" xmlns:epub="http://www.idpf.org/2007/ops">
<head><title>Navigation</title></head>
<body>
<nav epub:type="toc" id="toc">
<h2>Table of Contents</h2>
<ol>
{nav_entries}
</ol>
</nav>
</body>
</html>'''
        zf.writestr('OEBPS/nav.xhtml', nav_xhtml)
        manifest_items.append(f'<item id="nav" href="nav.xhtml" media-type="application/xhtml+xml" properties="nav"/>')

        # Chapters
        for ch_num, content in chapters:
            # Convert markdown-like content to XHTML
            # Strip any existing markdown headers
            lines = content.split('\n')
            html_lines = []
            in_paragraph = False

            for line in lines:
                stripped = line.strip()
                if not stripped:
                    if in_paragraph:
                        html_lines.append('</p>')
                        in_paragraph = False
                    continue

                # Check for scene breaks
                if stripped == '* * *' or stripped == '***' or stripped == '---':
                    if in_paragraph:
                        html_lines.append('</p>')
                        in_paragraph = False
                    html_lines.append('<p class="scene-break">* * *</p>')
                    continue

                # Check for markdown headers
                if stripped.startswith('#'):
                    if in_paragraph:
                        html_lines.append('</p>')
                        in_paragraph = False
                    header_text = stripped.lstrip('#').strip()
                    html_lines.append(f'<h3>{header_text}</h3>')
                    continue

                # Regular paragraph
                # Handle italic text (*text*)
                processed = re.sub(r'\*([^*]+)\*', r'<em>\1</em>', stripped)
                # Handle bold text (**text**)
                processed = re.sub(r'\*\*([^*]+)\*\*', r'<b>\1</b>', processed)

                if not in_paragraph:
                    html_lines.append(f'<p>{processed}')
                    in_paragraph = True
                else:
                    html_lines.append(f'<br/>{processed}')

            if in_paragraph:
                html_lines.append('</p>')

            chapter_html = '\n'.join(html_lines)

            ch_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>Chapter {ch_num}</title><link rel="stylesheet" href="styles.css"/></head>
<body>
<h2>Chapter {ch_num}</h2>
{chapter_html}
</body>
</html>'''

            zf.writestr(f'OEBPS/ch{ch_num:02d}.xhtml', ch_xhtml)
            manifest_items.append(f'<item id="ch{ch_num:02d}" href="ch{ch_num:02d}.xhtml" media-type="application/xhtml+xml"/>')
            spine_items.append(f'<itemref idref="ch{ch_num:02d}"/>')

        # Back matter - About the Author
        about_xhtml = f'''<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE html>
<html xmlns="http://www.w3.org/1999/xhtml">
<head><title>About the Author</title><link rel="stylesheet" href="styles.css"/></head>
<body>
<h2>About the Author</h2>
<p>Bob J Mills writes across hard sci-fi (space colonization, lunar settlements, Martian independence), business (AI, crisis management), and cozy mystery. He lives in New York City with a snake plant named Bertha and a printer that may or may not be sentient.</p>
<p><strong>Also by Bob J Mills:</strong></p>
<p><em>Business:</em> AI That Works, The Crisis Ready Company, Owner's Manual for AI Agents</p>
<p><em>The Age of Lightships:</em> Sunward Exodus, The Mercury Accord, Ghosts Beyond Neptune, The Last Photon Fleet</p>
<p><em>The Lunar Foundation:</em> Moon Rock, Mooncoming, Waters End, Waters Horizon</p>
<p><em>No Blue Sky:</em> Built from Dust, The Oxygen Gamble, Rivers Under Mars, The Red Charter, The First Martian Nation</p>
<p><em>Memoir:</em> Tomorrow Remembered</p>
<p><em>The Cindy Lou Legal Capers:</em> Retainer to Trouble, Clause for Alarm, Affidavits and Alibis</p>
<p><br/>Available on Amazon Kindle and Paperback.<br/>www.mifeco.com</p>
</body>
</html>'''
        zf.writestr('OEBPS/about.xhtml', about_xhtml)
        manifest_items.append(f'<item id="about" href="about.xhtml" media-type="application/xhtml+xml"/>')
        spine_items.append('<itemref idref="about"/>')

        # content.opf
        manifest_str = '\n    '.join(manifest_items)
        spine_str = '\n    '.join(spine_items)

        content_opf = f'''<?xml version="1.0" encoding="UTF-8"?>
<package version="3.0" xmlns="http://www.idpf.org/2007/opf" unique-identifier="uid">
  <metadata xmlns:dc="http://purl.org/dc/elements/1.1/">
    <dc:identifier id="uid">urn:isbn:978-SLUG-{book_num}</dc:identifier>
    <dc:title>{book_title}: {book_subtitle}</dc:title>
    <dc:creator>{author}</dc:creator>
    <dc:language>en</dc:language>
    <dc:date>{datetime.now().strftime("%Y-%m-%d")}</dc:date>
    <dc:publisher>MIFECO Press</dc:publisher>
    <meta property="dcterms:modified">{datetime.now().strftime("%Y-%m-%dT%H:%M:%SZ")}</meta>
  </metadata>
  <manifest>
    {manifest_str}
  </manifest>
  <spine>
    {spine_str}
  </spine>
</package>'''
        zf.writestr('OEBPS/content.opf', content_opf)

    size_mb = os.path.getsize(epub_path) / (1024 * 1024)
    print(f"EPUB created: {epub_path} ({size_mb:.1f} MB)")
    return epub_path

# Build EPUBs for all three books
books = [
    ("/home/bob/cindy-lou-series/book-1-retainer-to-trouble", "Retainer to Trouble", "A Cindy Lou Legal Caper", "The Cindy Lou Legal Capers", 1),
    ("/home/bob/cindy-lou-series/book-2-clause-for-alarm", "Clause for Alarm", "A Cindy Lou Legal Caper", "The Cindy Lou Legal Capers", 2),
    ("/home/bob/cindy-lou-series/book-3-affidavits-and-alibis", "Affidavits and Alibis", "A Cindy Lou Legal Caper", "The Cindy Lou Legal Capers", 3),
]

for book_dir, title, subtitle, series, num in books:
    if os.path.exists(book_dir):
        build_epub_manual(book_dir, title, subtitle, series, num)
    else:
        print(f"Directory not found: {book_dir}")

print("\nAll EPUBs built!")", "exit_code": 0, "error": null}

