    page-break-after: always;
}

.toc-page a {
    color: #000;
    text-decoration: none;
}

.toc-entry {
    margin: 0.4em 0;
    text-indent: 0;
}

.chapter {
    page-break-before: always;
}
'''

def md_to_html(text):
    """Convert markdown chapter text to HTML."""
    lines = text.split('\n')
    html_lines = []
    in_paragraph = False

    for line in lines:
        stripped = line.strip()
        if not stripped:
            if in_paragraph:
                html_lines.append('</p>\n')
                in_paragraph = False
            continue

        if stripped in ('* * *', '***', '---'):
            if in_paragraph:
                html_lines.append('</p>\n')
                in_paragraph = False
            html_lines.append('<p class="scene-break">* * *</p>\n')
            continue

        if stripped.startswith('#'):
            if in_paragraph:
                html_lines.append('</p>\n')
                in_paragraph = False
            header_text = stripped.lstrip('#').strip()
            html_lines.append(f'<h3>{header_text}</h3>\n')
            continue

        processed = re.sub(r'\*([^*]+)\*', r'<em>\1</em>', stripped)
        processed = re.sub(r'\*\*([^*]+)\*\*', r'<b>\1</b>', processed)

        if not in_paragraph:
            html_lines.append(f'<p>{processed}')
            in_paragraph = True
        else:
            html_lines.append(f' {processed}')

    if in_paragraph:
        html_lines.append('</p>\n')

    return ''.join(html_lines)

def build_print_pdf(book):
    """Build a print-ready PDF for one book."""
    book_dir = book["dir"]
    title = book["title"]
    slug = book["slug"]
    book_num = book["num"]
    chapters_dir = os.path.join(book_dir, "chapters")
    output_dir = os.path.join(book_dir, "output")
    os.makedirs(output_dir, exist_ok=True)

    # Collect chapters
    chapters = []
    for i in range(1, 31):
        ch_path = os.path.join(chapters_dir, f"ch{i:02d}.md")
        if os.path.exists(ch_path):
            with open(ch_path, 'r', encoding='utf-8') as f:
                content = f.read().strip()
                chapters.append((i, content))

    if not chapters:
        print(f"No chapters found for {title}")
        return

    year = datetime.now().year

    # Build HTML
    html_parts = [f'''<!DOCTYPE html>
<html>
<head>
<meta charset="UTF-8">
<title>{title}</title>
<style>{CSS}</style>
</head>
<body>
<div class="title-page">
<h1>{title}</h1>
<h2>{book["subtitle"]}</h2>
<p class="author">Bob J Mills</p>
</div>
<div class="copyright-page">
<p><strong>{title}</strong></p>
<p><em>{book["subtitle"]}</em></p>
<p>&copy; {year} Bob J Mills</p>
<p>All rights reserved.</p>
<p>This is a work of fiction. Names, characters, places, and incidents are either the product of the author's imagination or are used fictitiously.</p>
<p><br/><strong>The Cindy Lou Legal Capers — Book {book_num}</strong></p>
</div>
<div class="toc-page">
<h2>Contents</h2>
''']

    for ch_num, _ in chapters:
        html_parts.append(f'<p class="toc-entry"><a href="#ch{ch_num}">Chapter {ch_num}</a></p>\n')

    html_parts.append('</div>\n')

    for ch_num, content in chapters:
        chapter_html = md_to_html(content)
        html_parts.append(f'<div class="chapter" id="ch{ch_num}">\n')
        html_parts.append(f'<h3>Chapter {ch_num}</h3>\n')
        html_parts.append(chapter_html)
        html_parts.append('</div>\n')

    # About the author
    html_parts.append('''
<div class="chapter" id="about">
<h3>About the Author</h3>
<p>Bob J Mills writes across hard sci-fi (space colonization, lunar settlements, Martian independence), business (AI, crisis management), and cozy mystery. He lives in New York City.</p>
<p><strong>Also by Bob J Mills:</strong></p>
<p><em>Business:</em> AI That Works, The Crisis Ready Company, Owner's Manual for AI Agents</p>
<p><em>The Age of Lightships:</em> Sunward Exodus, The Mercury Accord, Ghosts Beyond Neptune, The Last Photon Fleet</p>
<p><em>The Lunar Foundation:</em> Moon Rock, Mooncoming, Waters End, Waters Horizon</p>
<p><em>No Blue Sky:</em> Built from Dust, The Oxygen Gamble, Rivers Under Mars, The Red Charter, The First Martian Nation</p>
<p><em>Memoir:</em> Tomorrow Remembered</p>
<p><em>The Cindy Lou Legal Capers:</em> Retainer to Trouble, Clause for Alarm, Affidavits and Alibis</p>
<p><br/>Available on Amazon Kindle and Paperback.<br/>www.mifeco.com</p>
</div>
</body>
</html>''')

    full_html = ''.join(html_parts)

    # Save HTML for debugging
    html_path = os.path.join(output_dir, f"{slug}_print.html")
    with open(html_path, 'w', encoding='utf-8') as f:
        f.write(full_html)

    # Generate PDF with WeasyPrint
    try:
        from weasyprint import HTML
        pdf_path = os.path.join(output_dir, f"{slug}_print.pdf"
        HTML(string=full_html, base_url=output_dir).write_pdf(pdf_path)
        size_mb = os.path.getsize(pdf_path) / (1024 * 1024)
        print(f"Print PDF: {pdf_path} ({size_mb:.1f} MB)")
    except ImportError:
        print(f"WeasyPrint not available. HTML saved to {html_path}")
    except Exception as e:
        print(f"PDF generation error for {title}: {e}")
        print(f"HTML saved to {html_path}")

# Build all three
for book in BOOKS:
    if os.path.exists(book["dir"]):
        build_print_pdf(book)

