{"content":""""
Core utilities: logging, state management, file hashing, chapter collection.
"""
import json, hashlib, re, logging, os
from pathlib import Path
from datetime import datetime, timezone
from .config import BOOK_REGISTRY, STATE_FILE

log = logging.getLogger("hermes-publish")

def slugify(text):
    return re.sub(r'[^a-z0-9]+', '-', text.lower()).strip('-')

def file_hash(path):
    if not path.exists():
        return ""
    h = hashlib.md5()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()

def dir_hash(dirpath, pattern="*.md"):
    if not dirpath.exists():
        return ""
    h = hashlib.md5()
    for f in sorted(dirpath.glob(pattern)):
        h.update(file_hash(f).encode())
    return h.hexdigest()

def load_state():
    if STATE_FILE.exists():
        with open(STATE_FILE) as f:
            return json.load(f)
    return {"books": {}}

def save_state(state):
    with open(STATE_FILE, "w") as f:
        json.dump(state, f, indent=2, default=str)

def src_hash(book):
    """Compute hash of a book's source files for change detection."""
    book_dir = book["dir"]
    mtype = book["manuscript_type"]
    if mtype == "chapters_md":
        return dir_hash(book_dir / "manuscript_src", "*.md")
    elif mtype == "chapters_xhtml":
        return dir_hash(book_dir / "manuscript_src", "*.xhtml")
    elif mtype == "manuscript_md":
        files = list(book_dir.glob("*MANUSCRIPT.md"))
        return file_hash(files[0]) if files else ""
    elif mtype == "single_md":
        return "".join(file_hash(f) for f in sorted(book_dir.glob("*.md")))
    return ""

def needs_rebuild(book_key, step, state):
    book = BOOK_REGISTRY[book_key]
    current = src_hash(book)
    stored = state.get("books", {}).get(book_key, {}).get(step, {}).get("src_hash", "")
    return stored != current

def mark_built(book_key, step, state):
    book = BOOK_REGISTRY[book_key]
    current = src_hash(book)
    state.setdefault("books", {}).setdefault(book_key, {})[step] = {
        "src_hash": current,
        "built_at": datetime.now(timezone.utc).isoformat(),
    }

def md_to_html_simple(text):
    lines = text.split('\n')
    out = []
    in_p = False
    for line in lines:
        s = line.strip()
        if not s:
            if in_p:
                out.append('</p>')
                in_p = False
            continue
        if s in ('* * *', '***', '---'):
            if in_p:
                out.append('</p>')
                in_p = False
            out.append('<p class="scene-break">* * *</p>')
            continue
        if s.startswith('#'):
            if in_p:
                out.append('</p>')
                in_p = False
            lv = len(s) - len(s.lstrip('#'))
            txt = s.lstrip('#').strip()
            tag = 'h3' if lv <= 3 else 'h4'
            out.append(f'<{tag}>{txt}</{tag}>')
            continue
        processed = re.sub(r'\*([^*]+)\*', r'<em>\1</em>', s)
        processed = re.sub(r'\*\*([^*]+)\*\*', r'<b>\1</b>', processed)
        if not in_p:
            out.append(f'<p>{processed}')
            in_p = True
        else:
            out.append(f'<br/>{processed}')
    if in_p:
        out.append('</p>')
    return '\n'.join(out)

def collect_chapters(book):
    book_dir = book["dir"]
    mtype = book["manuscript_type"]
    chapters = []

    if mtype in ("chapters_md", "chapters_xhtml"):
        src_dir = book_dir / "manuscript_src"
        if not src_dir.exists():
            return []
        glob_pat = "*.md" if mtype == "chapters_md" else "*.xhtml"
        for f in sorted(src_dir.glob(glob_pat)):
            num = int(re.search(r'(\d+)', f.stem).group(1)) if re.search(r'(\d+)', f.stem) else 0
            content = f.read_text(encoding="utf-8").strip()
            if mtype == "chapters_md":
                first = content.split('\n')[0] if content else ""
                title = first.lstrip('#').strip() if first.startswith('#') else f"Chapter {num}"
            else:
                tm = re.search(r'<h[12][^>]*>(.*?)</h[12]>', content, re.DOTALL)
                title = tm.group(1) if tm else f"Chapter {num}"
                content = re.sub(r'<\?xml[^?]*\?>', '', content)
                content = re.sub(r'<!DOCTYPE[^>]*>', '', content)
                content = re.sub(r'<html[^>]*>|</html>', '', content)
                content = re.sub(r'<head>.*?</head>', '', content, flags=re.DOTALL)
                content = re.sub(r'<body[^>]*>|</body>', '', content)
                content = content.strip()
            chapters.append((num, title, content))

    elif mtype == "manuscript_md":
        files = list(book_dir.glob("*MANUSCRIPT.md"))
        if files:
            content = files[0].read_text(encoding="utf-8")
            parts = re.split(r'\n(?=## Chapter )', content)
            ch_num = 0
            for part in parts:
                part = part.strip()
                if not part:
                    continue
                tm = re.match(r'##\s+(.+)', part)
                if tm:
                    ch_num += 1
                    chapters.append((ch_num, tm.group(1).strip(), part))

    elif mtype == "single_md":
        for i, f in enumerate(sorted(book_dir.glob("*.md")), 1):
            content = f.read_text(encoding="utf-8").strip()
            title = f.stem.replace('_', ' ').replace('-', ' ').title()
            chapters.append((i, title, content))

    return chapters
