Step 3: Generate print-ready PDF via WeasyPrint.
"""
from pathlib import Path
from datetime import datetime
from .config import BIBLIOGRAPHY
from .utils import slugify, collect_chapters, md_to_html_simple, log

PRINT_CSS = '''
@page { size: 6in 9in; margin: 0.75in 0.8in; @bottom-center { content: counter(page); font-size: 9pt; color: #666; } }
@page:first { @bottom-center { content: none; } }
body { font-family: "Times New Roman", Georgia, serif; font-size: 11pt; line-height: 1.5; color: #000; text-align: justify; }
h1 { font-size: 2em; font-weight: bold; text-align: center; margin-top: 30%; margin-bottom: 0.5em; page-break-before: always; }
h2 { font-size: 1.5em; font-weight: bold; text-align: center; margin-top: 2em; margin-bottom: 1em; page-break-before: always; }
h3 { font-size: 1.2em; font-weight: bold; text-align: center; margin-top: 1.5em; margin-bottom: 0.8em; page-break-before: always; }
p { text-indent: 1.5em; margin: 0; orphans: 2; widows: 2; }
.scene-break { text-align: center; margin: 1.2em 0; text-indent: 0; }
.title-page { page-break-after: always; }
.title-page h1 { font-size: 2.5em; margin-top: 35%; }
.title-page h2 { font-size: 1.3em; font-style: italic; font-weight: normal; page-break-before: auto; }
.title-page .author { font-size: 1.2em; margin-top: 3em; }
.copyright-page { font-size: 9pt; text-align: center; margin: 3em 1em; page-break-after: always; }
.toc-page { page-break-after: always; }
.toc-entry { margin: 0.4em 0; text-indent: 0; }
.chapter { page-break-before: always; }
'''

def run(book_key, book):
    log.info(f"  [{book_key}] Generating PDF...")
    try:
        from weasyprint import HTML
    except ImportError:
        HTML = None
        log.warning(f"  [{book_key}] WeasyPrint not installed, will generate HTML only")

    book_dir = book["dir"]
    out = book_dir / "output"
    out.mkdir(exist_ok=True)
    slug = slugify(book["title"])
    pdf_path = out / f"{slug}_Print.pdf"
    html_path = out / f"{slug}_print.html"
    chapters = collect_chapters(book)
    if not chapters:
        log.warning(f"  [{book_key}] No chapters found")
        return None

    year = datetime.now().year
    parts = [f'''<!DOCTYPE html><html><head><meta charset="UTF-8"><title>{book['title']}</title>
<style>{PRINT_CSS}</style></head><body>
<div class="title-page"><h1>{book['title']}</h1><h2>{book['subtitle']}</h2>
<p class="author">{book['author']}</p></div>
<div class="copyright-page"><p><strong>{book['title']}</strong></p><p><em>{book['subtitle']}</em></p>
<p>&copy; {year} {book['author']}</p><p>All rights reserved.</p>
<p><br/><strong>{book['series']} \u2014 Book {book['book_num']}</strong></p></div>
<div class="toc-page"><h2>Contents</h2>''']

    for cn, ct, _ in chapters:
        parts.append(f'<p class="toc-entry"><a href="#ch{cn}">Chapter {cn}: {ct}</a></p>\n')
    parts.append('</div>\n')

    for cn, ct, content in chapters:
        ch_html = md_to_html_simple(content) if book["manuscript_type"] in ("chapters_md", "manuscript_md") else content
        parts.append(f'<div class="chapter" id="ch{cn}"><h3>Chapter {cn}: {ct}</h3>\n{ch_html}</div>\n')

    parts.append('<div class="chapter" id="about"><h3>About the Author</h3>')
    parts.append('<p>Bob J Mills writes across hard sci-fi, business, and cozy mystery.</p>')
    parts.append('<p><strong>Also by Bob J Mills:</strong></p>')
    for sn, titles in BIBLIOGRAPHY.items():
        parts.append(f'<p><em>{sn}:</em> {", ".join(titles)}</p>\n')
    parts.append('<p><br/>Available on Amazon Kindle and Paperback.<br/>www.mifeco.com</p>')
    parts.append('</div></body></html>')

    full_html = ''.join(parts)
    html_path.write_text(full_html, encoding="utf-8")

    if HTML:
        try:
            HTML(string=full_html, base_url=str(out)).write_pdf(str(pdf_path))
            mb = pdf_path.stat().st_size / (1024 * 1024)
            log.info(f"  [{book_key}] PDF: {pdf_path} ({mb:.1f} MB)")
            return pdf_path
        except Exception as e:
            log.error(f"  [{book_key}] PDF error: {e}")
            return html_path
    else:
        log.info(f"  [{book_key}] HTML saved: {html_path}")
        return html_path
