"""
Condense a chapter by keeping key narrative elements and cutting ~55% of words.
"""
import re

def condense_chapter(content, target_ratio=0.45):
    lines = content.split('\n')
    title = lines[0] if lines else ""

    # Split into paragraphs
    paragraphs = []
    current = []
    for line in lines[1:]:
        stripped = line.strip()
        if not stripped:
            if current:
                paragraphs.append('\n'.join(current))
                current = []
        else:
            current.append(line)
    if current:
        paragraphs.append('\n'.join(current))

    result = [title, ""]

    for i, para in enumerate(paragraphs):
        if para.strip() in ('---', '* * *'):
            result.extend(["", "---", ""])
            continue
        if not para.strip():
            continue

        text = para.strip()
        sentences = re.split(r'(?<=[.!?])\s+', text)

        # Determine keep ratio
        quote_count = text.count('"')
        is_dialogue = quote_count >= 2
        key_terms = ['Moore', 'Webb', 'Noah', 'Olivia', 'Bennett', 'evidence', 'signature',
                     'filing', 'fraud', 'GPS', 'collar', 'hearing', 'arrest', 'deal',
                     'plea', 'shell', 'foundation', 'Bill', 'Ted', 'Ira', 'Emma', 'Liam']
        is_critical = sum(1 for t in key_terms if t in text) >= 2

        if i < 2 or i > len(paragraphs) - 2:
            keep_ratio = 0.80
        elif is_dialogue:
            keep_ratio = 0.70
        elif is_critical:
            keep_ratio = 0.50
        elif len(text.split()) < 25:
            keep_ratio = 0.65
        else:
            keep_ratio = 0.35

        if len(sentences) > 3:
            n = max(2, int(1 / keep_ratio))
            kept = []
            for j, s in enumerate(sentences):
                if j == 0:
                    kept.append(s)
                elif '"' in s:
                    kept.append(s)
                elif j % n == 0:
                    kept.append(s)
                elif len(s.split()) < 12 and j > 0:
                    kept.append(s)
            compressed = ' '.join(kept)
        else:
            compressed = text

        result.extend(["", compressed])

    return '\n'.join(result)

# Test on chapter 6
with open('/mnt/usb_4tb/books/Cindy_Lou_Legal_Capers/cindy-lou-series/book-1-retainer-to-trouble/chapters/ch06.md') as f:
    original = f.read()

condensed = condense_chapter(original)
orig_w = len(original.split())
new_w = len(condensed.split())
