{"new_string":"def md_to_html_simple(text):
    lines = text.split('\n')
    out = []
    in_p = False
    for line in lines:
        # Replace &nbsp; with &#160; for valid XHTML
        line = line.replace('&nbsp;', '&#160;')
        s = line.strip()
        if not s:
            if in_p:
                out.append('</p>')
                in_p = False
            continue
        if s in ('* * *', '***', '---'):
            if in_p:
                out.append('</p>')
                in_p = False
            out.append('<p class="scene-break">* * *</p>')
            continue
        if s.startswith('#'):
            if in_p:
                out.append('</p>')
                in_p = False
            lv = len(s) - len(s.lstrip('#'))
            txt = s.lstrip('#').strip()
            tag = 'h3' if lv <= 3 else 'h4'
            out.append(f'<{tag}>{txt}</{tag}>')
            continue
        processed = re.sub(r'\*([^*]+)\*', r'<em>\1</em>', s)
        processed = re.sub(r'\*\*([^*]+)\*\*', r'<b>\1</b>', processed)
        if not in_p:
            out.append(f'<p>{processed}')
            in_p = True
        else:
            out.append(f'<br/>{processed}')
